installer-gui-script.script:
function checkCompatibility() {
  if (system.version.ProductVersion.indexOf('15.') !== 0) {
    my.result.title='macOS incompatível';
    my.result.message='Este instalador foi validado somente no macOS 15 Sequoia em Hackintosh Intel.';
    return false;
  }
  return true;
}
